mapper.insert:
insert into sys_role_menu(role_code, fun_code) with recursive assignable_menu as ( select m.fun_code, m.parent_id from sys_menu m where m.status = '0' and (m.perms like 'tenant:%' or m.perms like 'purchase:%' or m.perms like 'inventory:%' or m.perms like 'production:%' or m.perms like 'finance:%' or m.perms like 'order:%' or m.perms like 'site:%' or m.perms like 'price:%' or m.perms like 'dashboard:%') union distinct select parent.fun_code, parent.parent_id from sys_menu parent join assignable_menu child on child.parent_id = parent.fun_code where parent.status = '0' ) select r.role_code, requested.fun_code from sys_role r join (
select #{funCode} as fun_code
) requested join sys_menu m on m.fun_code = requested.fun_code where r.role_code = #{roleCode} and r.role_type = 'TENANT' and r.system_flag = 1 and r.del_flag = '0' and m.fun_code in (select fun_code from assignable_menu)

mapper.delete:
delete relation_row
  from sys_shop_user_role relation_row
 where relation_row.shop_code = #{shopCode}
   and relation_row.role_code = #{roleCode}
   and relation_row.user_code <> #{userCode}
   and relation_row.user_code <> 'us1'

mapper.insert:
insert into sys_shop_user_role(shop_code, user_code, role_code, create_by, create_time)
select #{shopCode}, #{userCode}, #{roleCode}, #{operator}, sysdate()
 where not exists (
     select 1 from sys_shop_user_role
      where shop_code = #{shopCode}
        and user_code = #{userCode}
        and role_code = #{roleCode}
 )
